static void reveal(QWidget *widget){
 require(widget,"MATLAB Script Event control missing");
 for(auto *p=widget;p;p=p->parentWidget()){
  if(auto *scroll=qobject_cast<QScrollArea*>(p))scroll->ensureWidgetVisible(widget);
  if(auto *tabs=qobject_cast<QTabWidget*>(p))for(auto *page=widget;page&&page!=tabs;page=page->parentWidget())if(tabs->indexOf(page)>=0)tabs->setCurrentWidget(page);
 }
 events();acceptanceView(*widget);require(widget->isVisible()&&widget->isEnabled(),"MATLAB Script Event control unavailable");
}
